import json, pathlib, slim; d = slim.unpack(json.loads(pathlib.Path("docs/data.json").read_text()))
r = next(x for x in d["rankings"] if x["ticker"] == "MU"); num = den = 0
for f, c in d["factors"].items():
    x, s = r["raw"].get(f), d["z_stats"].get(f)
    if c["weight"] > 0 and x is not None and s:
        z = (min(max(x, s["lo"]), s["hi"]) - s["mean"]) / s["sd"] * c["sign"]
        num += c["weight"] * z; den += c["weight"]
print(f"{num / den:.2f}")
